insert into public.products (id, store_id, inventory_code, slug, title_ka, title_en, title_ru, description_ka, description_en, description_ru, category_id, condition, status, price, quantity, oem_number, featured, created_at, updated_at) values ('e0000000-0000-4000-8000-00000000001d', '11111111-1111-4111-8111-111111111111', 'AP-00029', 'toyota-camry-xv55-multimedia-display-ap-00029', 'მულტიმედიის ეკრანი — Toyota Camry XV55', 'Multimedia display — Toyota Camry XV55', 'Мультимедийный дисплей — Toyota Camry XV55', 'ორიგინალი ნაწილი — მულტიმედიის ეკრანი, მოხსნილი Toyota Camry XV55 (2015–2017)-დან. შემოწმებულია და მზადაა დასაყენებლად. ახალი ნაწილი, ტაივანური წარმოების. ფოტოებზე ნაჩვენებია რეალური ნაწილი. ნახვა შესაძლებელია ჩვენს მაღაზიაში თბილისში.', 'Genuine multimedia display removed from a Toyota Camry XV55 (2015–2017). Inspected and ready to fit. New part, made in Taiwan. Photos show the actual part. You can view it at our shop in Tbilisi.', 'Оригинальная деталь — мультимедийный дисплей, снята с Toyota Camry XV55 (2015–2017). Проверена и готова к установке. Новая деталь, производство Тайвань. На фото — реальная деталь. Можно осмотреть в нашем магазине в Тбилиси.', 'c0000000-0000-4000-8000-00000000000a', 'new', 'available', 560, 1, '86140-1LL', false, '2026-10-21T16:18:00.000Z', '2026-10-21T16:18:00.000Z') on conflict (id) do nothing;
